import{_ as t,o,c as a,ae as r}from"./chunks/framework.B2FZg54p.js";const n="/heidrun/experiments/web-doc-by-ai/documentation_images/files/new_file.png",m=JSON.parse('{"title":"Create a file or folder","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/create_a_file_or_folder.md","filePath":"documentation/create_a_file_or_folder.md"}'),i={name:"documentation/create_a_file_or_folder.md"};function s(l,e,d,c,h,f){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="create-a-file-or-folder" tabindex="-1">Create a file or folder <a class="header-anchor" href="#create-a-file-or-folder" aria-label="Permalink to &quot;Create a file or folder&quot;">​</a></h1><p>Create an empty file or folder in the intended location of the selected repository.</p><h2 id="choose-the-destination" tabindex="-1">Choose the destination <a class="header-anchor" href="#choose-the-destination" aria-label="Permalink to &quot;Choose the destination&quot;">​</a></h2><p>First, <a href="/heidrun/experiments/web-doc-by-ai/documentation/browse_project_files.html#select-an-existing-workspace">select an existing workspace</a>.</p><ol><li>Click <strong>Files</strong>, the first folder icon in the left sidebar icon bar, above <strong>Scripts</strong>, and click the folder rows needed to unfold the destination folders. Then select the destination using the table below.</li></ol><table tabindex="0"><thead><tr><th>Destination</th><th>Action</th></tr></thead><tbody><tr><td>Inside a folder</td><td>Click the folder row to select the folder.</td></tr><tr><td>Beside an existing file</td><td>Click the file row, then press <strong>Escape</strong> to close the large Git window; creation uses the folder containing the selected file.</td></tr><tr><td>At the repository root, outside any subfolder</td><td>If needed, click <strong>Collapse all folders</strong> to fold every folder, then click empty space outside all rows in the Files sidebar section to clear the selection. When nothing is selected, creation uses the repository root.</td></tr></tbody></table><p>If the rows still fill the Files sidebar section after folding, there is no separate control to clear the selection.</p><h2 id="create-the-file-or-folder" tabindex="-1">Create the file or folder <a class="header-anchor" href="#create-the-file-or-folder" aria-label="Permalink to &quot;Create the file or folder&quot;">​</a></h2><ol><li>Click <strong>New file</strong>, the file icon with a plus sign, or <strong>New folder</strong>, the folder icon with a plus sign, in the header of the Files sidebar section.</li><li>Type only the new name in the name box at the top of the contents of the destination folder, or at the top of the folder tree when creating at the repository root.</li></ol><p><img src="'+n+'" alt="New file name box inside docs with example.md typed before Enter is pressed."></p><ol start="3"><li>Press <strong>Enter</strong>.</li></ol><p>The new empty file or folder becomes the selected row. A new file also opens in the <a href="/heidrun/experiments/web-doc-by-ai/documentation/browse_project_files.html#open-a-project-file">large Git window described in Browse and open project files</a>.</p><p>A newly created folder that is still empty disappears from the folder tree when Heidrun restarts. The folder remains on disk.</p><h2 id="cancel-creation" tabindex="-1">Cancel creation <a class="header-anchor" href="#cancel-creation" aria-label="Permalink to &quot;Cancel creation&quot;">​</a></h2><ol><li>Press <strong>Escape</strong> while the name box is open, or click outside the name box.</li></ol><p>The name box closes without creating a file or folder.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><section class="documentation-troubleshooting-topic" aria-label="“un fichier ou dossier porte déjà ce nom” appears and the name box stays open"><h3 id="un-fichier-ou-dossier-porte-deja-ce-nom-appears-and-the-name-box-stays-open" tabindex="-1">“un fichier ou dossier porte déjà ce nom” appears and the name box stays open <a class="header-anchor" href="#un-fichier-ou-dossier-porte-deja-ce-nom-appears-and-the-name-box-stays-open" aria-label="Permalink to &quot;“un fichier ou dossier porte déjà ce nom” appears and the name box stays open&quot;">​</a></h3><p><strong>Cause</strong>: A file or folder with the entered name already exists in the destination folder.</p><p>The error appears in a small notification and is always in French, even with the English interface. The message means “a file or folder already has this name”.</p><p><strong>Solution</strong>:</p><ol><li>Replace the entered name with a name that is not already used in the destination folder.</li><li>Press <strong>Enter</strong>.</li></ol><p><strong>Check</strong>: The name box closes and the new file or folder becomes the selected row.</p></section><section class="documentation-troubleshooting-topic" aria-label="“A name cannot contain the character /. Select a folder first.” appears"><h3 id="a-name-cannot-contain-the-character-select-a-folder-first-appears" tabindex="-1">“A name cannot contain the character /. Select a folder first.” appears <a class="header-anchor" href="#a-name-cannot-contain-the-character-select-a-folder-first-appears" aria-label="Permalink to &quot;“A name cannot contain the character /. Select a folder first.” appears&quot;">​</a></h3><p><strong>Cause</strong>: The entered name contains <code>/</code> instead of being only a file or folder name.</p><p><strong>Solution</strong>:</p><ol><li>Remove <code>/</code> from the name in the name box, which remains open.</li><li>Press <strong>Enter</strong>.</li></ol><p><strong>Check</strong>: The new file or folder becomes the selected row inside the destination folder.</p></section><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/browse_project_files.html">Browse and open project files</a>: to select a workspace and view the new file.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/copy_a_file_path.html">Copy a file path</a>: to copy the path of the new file.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/files_sidebar_section_controls.html">Files sidebar section controls</a>: to identify the header buttons and changed-file letters.</li></ul>',21)])])}const b=t(i,[["render",s]]);export{m as __pageData,b as default};
